package dev.pivot.matrix;

import android.content.Context;
import android.graphics.*;
import java.io.*;
import java.util.*;

/** Local digit network; uncertain readings remain editable question marks. */
final class DigitReader {
 private final int[] sizes={784,128,64,10};
 private final float[][] weights=new float[3][],biases=new float[3][];
 DigitReader(Context context)throws IOException{try(DataInputStream input=new DataInputStream(new BufferedInputStream(context.getAssets().open("models/digits.bin")))){if(input.readInt()!=0x50564431)throw new IOException("Invalid digit model");for(int size:sizes)if(input.readInt()!=size)throw new IOException("Invalid model dimensions");for(int layer=0;layer<3;layer++){weights[layer]=new float[sizes[layer]*sizes[layer+1]];biases[layer]=new float[sizes[layer+1]];for(int i=0;i<weights[layer].length;i++)weights[layer][i]=input.readFloat();for(int i=0;i<biases[layer].length;i++)biases[layer][i]=input.readFloat();}}}
 static final class Prediction {final int digit;final double confidence,margin;Prediction(int digit,double confidence,double margin){this.digit=digit;this.confidence=confidence;this.margin=margin;}}
 Prediction predict(float[] pixels){float[] current=pixels;for(int layer=0;layer<3;layer++){float[] next=biases[layer].clone();for(int i=0;i<current.length;i++){float value=current[i];if(value==0)continue;int offset=i*next.length;for(int j=0;j<next.length;j++)next[j]+=value*weights[layer][offset+j];}if(layer<2)for(int j=0;j<next.length;j++)next[j]=Math.max(0,next[j]);current=next;}int best=0;for(int i=1;i<10;i++)if(current[i]>current[best])best=i;double sum=0,second=0;for(int i=0;i<10;i++){double p=Math.exp((current[i]-current[best])/1.4);sum+=p;if(i!=best)second=Math.max(second,p);}return new Prediction(best,1/sum,(1-second)/sum);}
 static float[] normalize(ScanImage image,Rect bounds){Bitmap glyph=Bitmap.createBitmap(bounds.width(),bounds.height(),Bitmap.Config.ARGB_8888);int[] source=new int[bounds.width()*bounds.height()];for(int y=0;y<bounds.height();y++)for(int x=0;x<bounds.width();x++)source[y*bounds.width()+x]=image.ink[(bounds.top+y)*image.width+bounds.left+x]!=0?Color.WHITE:Color.BLACK;glyph.setPixels(source,0,bounds.width(),0,0,bounds.width(),bounds.height());float scale=20f/Math.max(bounds.width(),bounds.height());int w=Math.max(1,Math.round(bounds.width()*scale)),h=Math.max(1,Math.round(bounds.height()*scale));Bitmap small=Bitmap.createScaledBitmap(glyph,w,h,true);int[] values=new int[w*h];small.getPixels(values,0,w,0,0,w,h);double sx=0,sy=0,total=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int value=Color.red(values[y*w+x]);sx+=x*value;sy+=y*value;total+=value;}int left=(int)Math.round(13.5-(total==0?w/2f:sx/total)),top=(int)Math.round(13.5-(total==0?h/2f:sy/total));float[] pixels=new float[784];for(int y=0;y<h;y++)for(int x=0;x<w;x++)if(left+x>=0&&left+x<28&&top+y>=0&&top+y<28)pixels[(top+y)*28+left+x]=Color.red(values[y*w+x])/255f;if(small!=glyph)small.recycle();glyph.recycle();return pixels;}
 static final class Result {final String text;final int uncertain;Result(String text,int uncertain){this.text=text;this.uncertain=uncertain;}}
 Result read(ScanImage image){List<ScanImage.Component> cells=new ArrayList<>(image.components);cells.removeIf(c->c.box.height()<3||c.area<4);if(cells.isEmpty()||cells.size()>160)return new Result("",0);List<Integer> heights=new ArrayList<>();for(ScanImage.Component cell:cells)if(cell.box.height()>6)heights.add(cell.box.height());if(heights.isEmpty())return new Result("",0);Collections.sort(heights);float median=heights.get(heights.size()/2);List<List<ScanImage.Component>> rows=new ArrayList<>();List<ScanImage.Component> small=new ArrayList<>();cells.sort(Comparator.comparingInt(c->c.box.centerY()));for(ScanImage.Component cell:cells){if(cell.box.height()<median*.45){small.add(cell);continue;}List<ScanImage.Component> found=null;for(List<ScanImage.Component> row:rows)if(Math.abs(row.get(0).box.centerY()-cell.box.centerY())<median*.6){found=row;break;}if(found==null){found=new ArrayList<>();rows.add(found);}found.add(cell);}for(ScanImage.Component cell:small){List<ScanImage.Component> nearest=null;float distance=Float.MAX_VALUE;for(List<ScanImage.Component> row:rows){float d=Math.abs(row.get(0).box.centerY()-cell.box.centerY());if(d<distance&&d<median*.8){nearest=row;distance=d;}}if(nearest!=null)nearest.add(cell);}if(rows.isEmpty()||rows.size()>5)return new Result("",0);StringBuilder text=new StringBuilder();int uncertain=0;for(List<ScanImage.Component> row:rows){row.sort(Comparator.comparingInt(c->c.box.left));if(text.length()>0)text.append('\n');int lastRight=-1;for(ScanImage.Component cell:row){Rect box=cell.box;if(lastRight>=0&&box.left-lastRight>median*.38)text.append(' ');char value;if(box.height()<median*.28&&box.width()>box.height()*2.0)value='-';else if(box.height()<median*.28&&box.width()<median*.28)value='.';else{Prediction prediction=predict(normalize(image,box));if(prediction.confidence<.82||prediction.margin<.45){value='?';uncertain++;}else value=(char)('0'+prediction.digit);}text.append(value);lastRight=box.right;}}return new Result(text.toString(),uncertain);}
}
